const Icon=({name,size=21})=>{const p={viewBox:'0 0 24 24',width:size,height:size,fill:'none',stroke:'currentColor',strokeWidth:1.9,strokeLinecap:'round',strokeLinejoin:'round'};const x={home:<><path d="m3 10 9-7 9 7"/><path d="M5 9v11h14V9"/></>,book:<><path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v17H6.5A2.5 2.5 0 0 0 4 22z"/><path d="M4 5.5v14A2.5 2.5 0 0 1 6.5 17H20"/></>,learn:<><path d="M4 5h16v12H4z"/><path d="m8 21 4-4 4 4"/></>,user:<><circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/></>,shield:<><path d="M12 3 20 6v5c0 5-3.5 8.5-8 10-4.5-1.5-8-5-8-10V6z"/><path d="m9 12 2 2 4-5"/></>,bell:<><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></>,moon:<><path d="M20 15.5A8 8 0 1 1 8.5 4 8 8 0 0 0 20 15.5z"/></>,sun:<><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2"/></>};return <svg className="i" {...p}>{x[name]||x.home}</svg>};
const Simple=({title,children})=><section className="sec"><div className="hero inner"><h1>{title}</h1></div><div className="card">{children}</div></section>;
const AuthRedirect=()=> <Simple title="Sign in to continue"><p className="mu">Please sign in to continue to this part of TAMP.</p><Link className="btn" to="/login">Sign in</Link></Simple>;
const money=n=>new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0}).format(Number(n)||0);
const fmt=d=>new Date(d).toLocaleString('en-NG',{dateStyle:'medium',timeStyle:'short'});
const videoId=u=>{try{const x=new URL(u);return x.searchParams.get('v')||x.pathname.split('/').filter(Boolean).pop()}catch{return null}};

async function settings(){const{data,error}=await supabase.from('site_settings').select('*');if(error)throw error;return Object.fromEntries((data||[]).map(x=>[x.key,x.value]))}
async function course(){const{data,error}=await supabase.from('courses').select('*').eq('id','da').single();if(error)throw error;return data}
async function levels(){const{data,error}=await supabase.from('course_levels').select('*').eq('course_id','da').order('level_number');if(error)throw error;return data||[]}
async function stats(){const{data,error}=await supabase.rpc('course_enrollment_stats',{p_course_id:'da'});if(error)throw error;return data||{enrolled:0,active:0,countries:[]}}
async function profileUpdate(form){return updateMyProfile(form)}

function Layout({user,profile,children}){const[d,setD]=useState(()=>localStorage.getItem('th')==='dark');const loc=useLocation();const auth=['/login','/signup','/auth/confirm'].includes(loc.pathname);const appPaths=['/learn','/assignments/da','/grades','/profile','/notifications','/admin','/transcript','/certificates'];const isApp=!!user&&(loc.pathname==='/'||appPaths.includes(loc.pathname)||loc.pathname.startsWith('/quiz/'));const isPublic=!auth&&!isApp;useEffect(()=>{document.documentElement.dataset.theme=d?'dark':'light';localStorage.setItem('th',d?'dark':'light');document.body.classList.toggle('tamp-app',isApp);document.body.classList.toggle('tamp-public',isPublic);return()=>{document.body.classList.remove('tamp-app','tamp-public')}},[d,isApp,isPublic]);return <div className={'app-shell '+(isApp?'app-campus':'public-site')}><Seo path={loc.pathname}/>{!auth&&<header className={'top '+(isApp?'app-top':'public-top')}><Link className="logo" to="/">TAMP<span className="logo-dot">.</span></Link>{isPublic?<><nav className="public-nav"><Link to="/courses">Courses</Link><Link to="/verify">Verify</Link><Link to="/students">Students</Link></nav><div className="top-actions"><Link className="public-signin" to={user?'/learn':'/login'}>{user?'Learning space':'Sign in'}</Link><button className="ib" onClick={()=>setD(!d)}><Icon name={d?'sun':'moon'}/></button></div></>:<div className="top-actions">{user&&<Link className="ib" to="/notifications"><Icon name="bell"/></Link>}<button className="ib" onClick={()=>setD(!d)}><Icon name={d?'sun':'moon'}/></button></div>}</header>}<main>{children}</main>{isApp&&<nav className="tabs"><NavLink to="/" end className={({isActive})=>isActive?'on':''}><Icon name="home"/><span>Home</span></NavLink><NavLink to="/learn" className={({isActive})=>isActive?'on':''}><Icon name="learn"/><span>Learn</span></NavLink><NavLink to="/courses" className={({isActive})=>isActive?'on':''}><Icon name="book"/><span>Course</span></NavLink><NavLink to="/profile" className={({isActive})=>isActive?'on':''}><Icon name="user"/><span>Me</span></NavLink></nav>}</div>}

function Home({user,profile}){const[c,setC]=useState(null),[s,setS]=useState(null),[set,setSet]=useState({});useEffect(()=>{Promise.all([course(),stats(),settings()]).then(([a,b,d])=>{setC(a);setS(b);setSet(d)}).catch(()=>{})},[]);return <section className="sec home-page"><div className="hero"><p className="eyebrow">TAMP · Technical Campus</p><h1>{user?'Welcome back, '+(profile?.full_name||'learner'):'Technical learning, without the noise.'}</h1><p className="lead">Data Analysis is currently available through the TAMP cohort programme.</p><Link className="btn" to="/courses/da">Open Data Analysis</Link></div>{c&&<div className="card course-feature"><div className="course-feature-head"><span className="pill">CURRENT PROGRAMME</span><span className="home-price">₦{Number(set.enrollment_price_ngn||2000).toLocaleString()}</span></div><h2>{c.title}</h2><p className="mu">{c.description}</p><div className="meta big"><span>21 Oct 2026</span><span>Beginner</span><span>5-day journeys</span></div>{s&&<div className="stats"><div><b>{s.enrolled||0}</b><span>enrolled</span></div><div><b>{(s.countries||[]).length}</b><span>countries</span></div><div><b>₦{Number(set.enrollment_price_ngn||2000).toLocaleString()}</b><span>fee</span></div></div>}<Link className="btn" to="/courses/da">View programme</Link></div>}<div className="home-links"><Link to="/handbook">Academic handbook</Link><Link to="/curriculum">Curriculum</Link><Link to="/privacy">Privacy</Link><Link to="/verify">Certificate verification</Link></div></section>}

function Courses(){return <section className="sec"><div className="hero inner"><p className="eyebrow">2026 cohort</p><h1>Data Analysis</h1><p className="mu">TAMP currently has one course only. Tap through for the full curriculum, schedule and enrollment.</p></div><CourseDetail/></section>}

function CourseDetail(){
 const[c,setC]=useState(null),[ls,setLs]=useState([]),[s,setS]=useState(null),[set,setSet]=useState({});
 const nav=useNavigate();
 useEffect(()=>{Promise.all([course(),levels(),stats(),settings()]).then(([a,b,d,e])=>{setC(a);setLs(b);setS(d);setSet(e)}).catch(()=>{})},[]);
 const now=Date.now();
 const activeIndex=ls.findIndex(l=>now>=new Date(l.opens_at).getTime()&&now<=new Date(l.closes_at).getTime());
 const nextIndex=ls.findIndex(l=>new Date(l.opens_at).getTime()>now);
 const focusIndex=activeIndex>=0?activeIndex:(nextIndex>=0?nextIndex:Math.max(0,ls.length-1));
 if(!c)return <div className="card">Preparing your course…</div>;
 const vid=videoId(set.course_youtube_url||ls[focusIndex]?.youtube_url||ls[0]?.youtube_url);
 return <div className="course-detail course-detail-modern">
  <div className="course-hero-card">
   <div><span className="eyebrow">DATA ANALYSIS · 2026 COHORT</span><h1>{c.title}</h1><p className="course-hero-copy">A structured path from Beginner foundations to advanced analysis and a final project.</p></div>
   <div className="course-hero-meta"><span>₦{Number(set.enrollment_price_ngn||2000).toLocaleString()}</span><span>Starts 21 Oct 2026</span><span>5-day journeys</span></div>
  </div>
  {vid&&<div className="video-wrap course-video"><iframe src={'https://www.youtube.com/embed/'+vid} title="Data Analysis course introduction" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen/></div>}
  <div className="card course-overview"><div className="section-head"><div><p className="eyebrow">PROGRAMME</p><h2>Data Analysis</h2></div></div><p className="mu">Learn the foundations first. Each five-day journey unlocks on schedule, with the current week kept in focus.</p><div className="chips"><span>Excel</span><span>Google Sheets</span><span>Python</span><span>pandas</span><span>Analysis</span></div></div>
  <div className="curriculum-stack"><div className="curriculum-heading"><div><p className="eyebrow">CURRICULUM</p><h2>Your learning path</h2></div><span>{Math.max(0,focusIndex+1)} / {ls.length} current</span></div>{ls.map((l,i)=><LevelCard key={l.id} level={l} user={null} current={i===focusIndex}/>)}</div>
  {s&&<div className="course-stats-strip"><div><b>{s.enrolled||0}</b><span>enrolled</span></div><div><b>{(s.countries||[]).length}</b><span>countries</span></div><div><b>1–2 mo</b><span>cohort</span></div></div>}
  <div className="card enroll-cta"><div><p className="eyebrow">JOIN THE COHORT</p><h2>Ready to begin?</h2><p className="mu">Enrollment is ₦{Number(set.enrollment_price_ngn||2000).toLocaleString()}.</p></div><button className="btn" onClick={()=>nav('/payment')}>Pay ₦{Number(set.enrollment_price_ngn||2000).toLocaleString()} online</button><button className="btn o" onClick={()=>nav('/enroll/da')}>I already have an enrollment code</button></div>
 </div>
}function DailyFeedback({level,day,onClose}){const[rating,setRating]=useState(0),[comment,setComment]=useState(''),[busy,setBusy]=useState(false),[done,setDone]=useState(false);const send=async()=>{if(!rating||comment.trim().length<3)return;setBusy(true);try{await submitDailyFeedback({courseId:'da',journeyNumber:level.journey_number||level.level_number,dayNumber:day,rating,comment});setDone(true);setTimeout(onClose,700)}catch{}finally{setBusy(false)}};if(done)return <div className="feedback-modal"><div className="feedback-sheet"><div className="success-icon success"><Icon name="shield"/></div><h2>Thanks for the feedback</h2><p className="mu">Your response helps TAMP improve the learning experience.</p></div></div>;return <div className="feedback-modal"><div className="feedback-sheet"><button className="feedback-close" onClick={onClose}>×</button><span className="eyebrow">DAY {day} COMPLETE</span><h2>How was today’s learning?</h2><p className="mu">Tell us what helped and what we could improve.</p><div className="rating-row">{[1,2,3,4,5].map(n=><button key={n} className={rating>=n?'active':''} onClick={()=>setRating(n)}>★</button>)}</div><textarea value={comment} onChange={e=>setComment(e.target.value)} placeholder="Your feedback…"/><button className="btn" disabled={!rating||comment.trim().length<3||busy} onClick={send}>{busy?'Sending feedback…':'Send feedback'}</button></div></div>}

